const seed=[['+5511999900101','Marina Costa','Lumina Contabilidade','qualified','hot',85,'bot','Automatizar triagem e propostas. Prazo de 30 dias.'],['+5511999900102','Rafael Lima','Estúdio Forma','qualifying','warm',60,'bot','Organizar pedidos que chegam pelo WhatsApp.'],['+5511999900103','Beatriz Alves','Norte Educação','meeting','hot',100,'human','Reduzir tarefas manuais de matrícula e integrar atendimento.'],['+5511999900104','Lucas Oliveira','Ateliê Lume','new','unknown',0,'bot','Primeiro contato recebido.'],['+5511999900105','Camila Rocha','Vértice Serviços','qualifying','cold',25,'paused','Conhecendo possibilidades, ainda sem prazo.'],['+5511999900106','Pedro Martins','Nova Gestão','won','hot',85,'human','Projeto de automação aprovado.']];
function resetDemo(){leads=seed.map((a,i)=>({phone:a[0],name:a[1],company:a[2],stage:a[3],temperature:a[4],score:a[5],mode:a[6],summary:a[7],channel:'telegram',email:'',revision:1,reasons:[...(a[5]>=60?[{label:'Aderência ao serviço',points:35}]:[]),...(a[5]>=25?[{label:'Necessidade declarada',points:25}]:[]),...(a[5]>=85?[{label:'Prazo de até 30 dias',points:25}]:[]),...(a[5]===100?[{label:'Participa da decisão',points:15}]:[])],qualification:{need:a[7],urgency:i%2?'unknown':'30_days',decision:'unknown'},updated_at:new Date(Date.now()-i*900000).toISOString(),created_at:today.toISOString(),handoff_requested_at:i===0?today.toISOString():null}));messages=leads.flatMap(l=>[{id:crypto.randomUUID(),phone:l.phone,direction:'in',author:'lead',body:`Olá! Sou ${l.name}, da ${l.company}. ${l.summary}`,created_at:today.toISOString(),status:'received'},{id:crypto.randomUUID(),phone:l.phone,direction:'out',author:'bot',body:`Olá, ${l.name.split(' ')[0]}! Sou a assistente virtual da Órbita. Para entender melhor: qual etapa do processo mais toma tempo da sua equipe hoje?`,created_at:today.toISOString(),status:'sent'}]);slots=[];for(let d=1;d<=10;d++){const day=new Date();day.setDate(day.getDate()+d);if([0,6].includes(day.getDay()))continue;for(const h of [10,14,16]){day.setHours(h,0,0,0);slots.push({id:crypto.randomUUID(),resource:'Consultor',starts_at:day.toISOString(),ends_at:new Date(+day+1800000).toISOString(),enabled:true})}}bookings=[{id:'demo-booking',phone:leads[2].phone,slot_id:slots[0].id,status:'confirmed'}];tasks=[{id:'demo-task',phone:leads[0].phone,title:'Lead quente: assumir conversa',status:'open',due_at:new Date(Date.now()+900000).toISOString()}];settings={business_name:'Órbita Automação',business_context:'Automação e IA para serviços B2B. Diagnóstico inicial de 30 minutos.',hot_threshold:70,warm_threshold:40,sla_minutes:15};selected=leads[0].phone;}
function toast(m){const e=document.querySelector('#toast');e.textContent=m;e.style.display='block';clearTimeout(timer);timer=setTimeout(()=>e.style.display='none',5500)}
function badge(l){return `<span class="badge ${{hot:'hot',warm:'warm',cold:'cold',unknown:''}[l.temperature]}">${{hot:'Quente',warm:'Morno',cold:'Frio',unknown:'A qualificar'}[l.temperature]}</span>`}
function modeLabel(l){return {bot:'IA em atendimento',human:'Atendimento humano',paused:'IA pausada',optout:'Contato encerrado'}[l.mode]}
function date(v){return new Date(v).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}
function filtered(){return leads.filter(l=>(!temperature||l.temperature===temperature)&&[l.name,l.company,l.phone].join(' ').toLowerCase().includes(search.toLowerCase()))}
const originalRender=render;
render=()=>{originalRender();document.querySelector('#connection').textContent=demo?'Demonstração · dados ilustrativos':session?connectionState:'Acesso restrito';document.querySelector('#mode').onclick=async()=>{if(demo)showLogin();else{if(realtime)await db.removeChannel(realtime);clearTimeout(refreshTimer);await db.auth.signOut();demo=true;session=null;for(const k in drafts)delete drafts[k];resetDemo();render()}}};
renderView=()=>{const c=document.querySelector('#content');c.innerHTML=`<div class="heading"><div><h1>${({kanban:'Seu funil, em movimento',inbox:'O contexto vem junto',calendar:'Espaço para boas conversas',flow:'Da mensagem à oportunidade',settings:'Seu processo, suas regras',simulator:'Veja o atendimento acontecer'})[view]}</h1><p>${({kanban:'Da primeira mensagem à próxima oportunidade.',inbox:'Acompanhe a IA e assuma quando fizer sentido.',calendar:'Sua disponibilidade. Suas reuniões. Sem outra ferramenta.',flow:'Uma operação simples de acompanhar e explicar.',settings:'Critérios claros deixam a operação previsível.',simulator:'Converse como lead e acompanhe o CRM ao lado.'})[view]}</p></div>${view==='kanban'?'<button class="primary" id="newlead">＋ Novo lead</button>':view==='calendar'?'<button class="primary" id="newslot">＋ Abrir horário</button>':''}</div>${demo?'<div class="notice">Você está na demonstração interativa, com dados fictícios. As mudanças aqui são temporárias e não enviam mensagens. Use <b>Conectar meu CRM</b> para acessar os dados reais.</div>':''}<div id="surface"></div>`;if(view==='kanban')kanban();if(view==='inbox')inbox();if(view==='calendar')calendar();if(view==='flow')flow();if(view==='settings')configuration();if(view==='simulator')simulator();document.querySelector('#newlead')?.addEventListener('click',newLead);document.querySelector('#newslot')?.addEventListener('click',newSlot)};
function kanban(){const ls=filtered();document.querySelector('#surface').innerHTML=`<div class="metrics">${[[leads.length,'Leads no funil','Identificados pelo telefone'],[leads.filter(l=>l.temperature==='hot'&&!['won','lost'].includes(l.stage)).length,'Prontos para conversar','Aderência + intenção'],[bookings.filter(b=>b.status==='confirmed').length,'Reuniões confirmadas','Agenda própria'],[tasks.filter(t=>t.status==='open').length,'Aguardando humano','Próxima ação definida']].map(x=>`<div class="metric"><div class="metric-title">${x[1]}</div><div class="metric-value">${x[0]}</div><small>${x[2]}</small></div>`).join('')}</div><div class="toolbar"><input id="search" placeholder="Buscar nome, empresa ou telefone" aria-label="Buscar lead" value="${esc(search)}"><select id="temp" aria-label="Filtrar temperatura"><option value="">Todas as temperaturas</option>${[['hot','Quentes'],['warm','Mornos'],['cold','Frios'],['unknown','A qualificar']].map(a=>`<option value="${a[0]}" ${a[0]===temperature?'selected':''}>${a[1]}</option>`).join('')}</select><small class="right">${ls.length} leads · arraste para mover</small></div><div class="board">${stages.map(st=>`<section class="column" data-stage="${st[0]}"><div class="col-head"><span><i style="--col:${st[2]}"></i>${st[1]}</span><span class="count">${ls.filter(l=>l.stage===st[0]).length}</span></div>${ls.filter(l=>l.stage===st[0]).map(l=>`<button class="lead-card" draggable="true" data-phone="${l.phone}"><div class="card-top">${badge(l)}<span class="muted" style="font-size:10px">${esc(l.channel)}</span></div><h3>${esc(l.name||'Novo contato')}</h3><p>${esc(l.company||l.phone)}</p><div class="card-score"><span class="bar"><span style="width:${l.score}%"></span></span><span>${l.score}/100</span></div><div class="card-foot"><span>${modeLabel(l)}</span><span>${l.handoff_requested_at&&!l.human_owner?'◷ Prioridade':'↗ Abrir'}</span></div></button>`).join('')||'<div class="empty">O próximo lead pode estar<br>na próxima conversa.</div>'}</section>`).join('')}</div>${ls.some(l=>l.stage==='lost')?'<p class="muted">Leads encerrados: '+ls.filter(l=>l.stage==='lost').map(l=>esc(l.name||l.phone)).join(', ')+'</p>':''}`;document.querySelector('#search').oninput=e=>{search=e.target.value;kanban();const f=document.querySelector('#search');f.focus();f.setSelectionRange(search.length,search.length)};document.querySelector('#temp').onchange=e=>{temperature=e.target.value;kanban()};document.querySelectorAll('.lead-card').forEach(b=>{b.onclick=()=>openLead(b.dataset.phone);b.ondragstart=e=>e.dataTransfer.setData('text/plain',b.dataset.phone)});document.querySelectorAll('[data-stage]').forEach(col=>{col.ondragover=e=>e.preventDefault();col.ondrop=async e=>{e.preventDefault();await action('stage',{phone:e.dataTransfer.getData('text/plain'),stage:col.dataset.stage})}})}
function openLead(phone){selected=phone;view='inbox';render()}
function inbox(){const l=leads.find(l=>l.phone===selected)||leads[0];if(!l){document.querySelector('#surface').innerHTML='<div class="panel empty">Nenhuma conversa ainda. Conecte o Telegram e compartilhe seu contato com o bot.</div>';return}selected=l.phone;const msgs=messages.filter(m=>m.phone===l.phone);const pending=tasks.filter(t=>t.phone===l.phone&&t.status==='open');document.querySelector('#surface').innerHTML=`<div class="split"><div class="inbox-list">${leads.map(x=>`<button class="inbox-row ${x.phone===l.phone?'selected':''}" data-lead="${x.phone}"><div style="display:flex;justify-content:space-between;gap:6px"><strong>${esc(x.name||'Novo contato')}</strong>${badge(x)}</div><small>${esc(x.company||x.phone)}</small><small>${modeLabel(x)}</small></button>`).join('')}</div><section class="conversation"><div class="chat-head"><div><h3>${esc(l.name||l.phone)}</h3><small>${esc(l.phone)} · ${esc(l.channel)}</small></div><div class="actions"><span class="badge ${l.mode==='bot'?'blue':'green'}">${modeLabel(l)}</span><button id="take" class="${l.mode==='human'?'':'primary'}" ${l.mode==='optout'?'disabled':''}>${l.mode==='human'?'Retomar IA':'Assumir'}</button><button id="pause" ${l.mode==='optout'?'disabled':''}>${l.mode==='paused'?'Retomar':'Pausar'}</button></div></div>${pending.length?`<div class="notice" style="margin:14px 18px 0">${esc(pending[0].title)} · ${new Date(pending[0].due_at)<new Date()?'SLA vencido — atenção do operador':'Atender até '+date(pending[0].due_at)}. A IA só para quando você assume ou pausa.</div>`:''}<div class="chat-body">${msgs.map(m=>`<div class="bubble ${m.direction==='out'?'out':''}">${esc(m.body)}<small>${esc({lead:'Lead',bot:'Assistente IA',human:'Operador',system:'Sistema'}[m.author])} · ${date(m.created_at)} · ${esc({received:'recebida',pending:'na fila',sending:'enviando',sent:'enviada',failed:'falhou',uncertain:'conferir entrega',cancelled:'cancelada'}[m.status])}${m.error?' · '+esc(m.error):''}</small></div>`).join('')||'<div class="empty">Sem mensagens neste contato.</div>'}</div><form class="composer" id="composer"><textarea id="reply" aria-label="Mensagem do operador" placeholder="${l.mode==='human'?'Escreva sua mensagem…':'Assuma a conversa para responder'}" ${l.mode!=='human'?'disabled':''}></textarea><button class="primary" ${l.mode!=='human'?'disabled':''}>Enviar</button></form></section><aside class="profile"><h3>Sobre este lead <button style="padding:4px 8px;float:right" id="edit">Editar</button></h3>${badge(l)}<div class="scorebox"><strong style="font-size:24px">${l.score}<span style="font-size:12px;color:#8b96a7"> / 100</span></strong><p class="muted" style="font-size:11px;margin-top:5px">Por que esta pontuação?</p>${(l.reasons||[]).map(r=>`<div class="reason"><span>${esc(r.label)}</span><strong>+${r.points}</strong></div>`).join('')||'<div class="reason">Ainda faltam informações.</div>'}</div><label>Etapa comercial<select id="stage">${[...stages,['lost','Encerrado']].map(s=>`<option value="${s[0]}" ${s[0]===l.stage?'selected':''}>${s[1]}</option>`).join('')}</select></label><dl><dt>Empresa</dt><dd>${esc(l.company||'A descobrir')}</dd><dt>E-mail</dt><dd>${esc(l.email||'Não informado')}</dd><dt>Resumo para o vendedor</dt><dd>${esc(l.summary||'Aguardando qualificação.')}</dd><dt>Responsável humano</dt><dd>${esc(l.human_owner||'Ainda não assumido')}</dd></dl><button id="book" style="width:100%;margin-top:16px">Agendar reunião</button><h3 class="section-title">Histórico de decisões</h3>${events.filter(e=>e.phone===l.phone).slice(0,5).map(e=>`<p class="muted" style="font-size:10px;margin-bottom:10px">${esc(e.kind)} · ${date(e.created_at)}</p>`).join('')||'<small>As alterações ficam registradas.</small>'}</aside></div>`;document.querySelectorAll('[data-lead]').forEach(b=>b.onclick=()=>{selected=b.dataset.lead;inbox()});document.querySelector('#take').onclick=()=>action('mode',{phone:l.phone,mode:l.mode==='human'?'bot':'human'});document.querySelector('#pause').onclick=()=>action('mode',{phone:l.phone,mode:l.mode==='paused'?'bot':'paused'});document.querySelector('#stage').onchange=e=>action('stage',{phone:l.phone,stage:e.target.value});document.querySelector('#edit').onclick=()=>editLead(l);document.querySelector('#book').onclick=()=>bookLead(l);const field=document.querySelector('#reply');field.value=drafts[l.phone]||'';field.oninput=()=>drafts[l.phone]=field.value;document.querySelector('#composer').onsubmit=async e=>{e.preventDefault();const body=field.value.trim();if(!body)return;const btn=e.target.querySelector('button');btn.disabled=true;try{drafts[l.phone]='';field.value='';await action('send',{phone:l.phone,body,request_id:crypto.randomUUID()})}catch{drafts[l.phone]=body;const input=document.querySelector('#reply');if(input)input.value=body}finally{btn.disabled=false}};const cb=document.querySelector('.chat-body');cb.scrollTop=cb.scrollHeight}
function calendar(){const days=[...new Set(slots.filter(s=>s.enabled).map(s=>new Date(s.starts_at).toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'})))].sort().slice(0,10);document.querySelector('#surface').innerHTML=`<div class="notice">Horários de Brasília · reuniões de 30 minutos · a confirmação reserva o horário de forma exclusiva. Abrir disponibilidade não envia convites.</div><div class="calendar">${days.map(d=>`<div class="day"><h3>${new Date(d+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'short',day:'2-digit',month:'short'})}</h3>${slots.filter(s=>s.enabled&&new Date(s.starts_at).toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'})===d).map(s=>{const b=bookings.find(b=>b.slot_id===s.id&&b.status==='confirmed');return `<button class="slot ${b?'booked':''}" data-slot="${s.id}"><b>${date(s.starts_at).split(', ')[1]||date(s.starts_at)}</b><br><span>${b?esc(leads.find(l=>l.phone===b.phone)?.name||b.phone):'Disponível'}</span><br><small>${esc(s.resource)}</small></button>`}).join('')}</div>`).join('')||'<div class="panel empty">Abra os primeiros horários para que o bot possa oferecer sua agenda.</div>'}</div><h2 class="section-title">Próximas reuniões</h2><div class="panel"><table class="table"><thead><tr><th>Lead</th><th>Quando</th><th>Responsável</th><th></th></tr></thead><tbody>${bookings.filter(b=>b.status==='confirmed').map(b=>{const s=slots.find(s=>s.id===b.slot_id);return `<tr><td>${esc(leads.find(l=>l.phone===b.phone)?.name||b.phone)}</td><td>${s?date(s.starts_at):'—'}</td><td>${esc(s?.resource)}</td><td><button data-cancel="${b.id}">Cancelar reserva</button></td></tr>`}).join('')||'<tr><td colspan="4">Nenhuma reunião confirmada.</td></tr>'}</tbody></table></div>`;document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{const booked=bookings.find(x=>x.slot_id===b.dataset.slot&&x.status==='confirmed');if(booked)openLead(booked.phone);else modal('Horário disponível',`<p>Selecione um lead na área Conversas para agendar este horário, ou feche a disponibilidade abaixo.</p>`,async()=>action('close_slot',{id:b.dataset.slot}),'Fechar horário')});document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>modal('Cancelar esta reunião?',`<p>O horário será liberado. Avise o lead pela conversa se necessário.</p>`,()=>action('cancel_booking',{id:b.dataset.cancel}),'Cancelar reserva'))}
function modal(title,body,save,label='Salvar'){document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.innerHTML=`<h2>${title}</h2><form id="modalform">${body}<div class="actions"><button type="button" id="dismiss">Voltar</button><button class="primary">${label}</button></div></form>`;document.body.append(d);d.querySelector('#dismiss').onclick=()=>d.close();d.querySelector('form').onsubmit=async e=>{e.preventDefault();const btn=d.querySelector('.primary');btn.disabled=true;try{await save(new FormData(e.target));d.close()}catch(err){toast(err.message)}finally{btn.disabled=false}};d.showModal()}
function newLead(){modal('Adicionar lead',`<div class="formgrid"><label>Nome<input name="name" maxlength="120" required></label><label>Empresa<input name="company" maxlength="160"></label><label class="wide">Telefone com código do país<input name="phone" placeholder="+5511999999999" pattern="\\+[1-9][0-9]{7,14}" required></label></div>`,f=>action('create_lead',Object.fromEntries(f)))}
function editLead(l){modal('Editar contato',`<div class="formgrid"><label>Nome<input name="name" value="${esc(l.name)}"></label><label>Empresa<input name="company" value="${esc(l.company)}"></label><label class="wide">E-mail<input type="email" name="email" value="${esc(l.email)}"></label><small class="wide">Telefone preservado como identificador: ${esc(l.phone)}</small></div>`,f=>action('edit',{phone:l.phone,...Object.fromEntries(f)}))}
function newSlot(){modal('Abrir disponibilidade',`<div class="formgrid"><label>Dia<input type="date" name="day" required></label><label>Hora de Brasília<input type="time" name="time" required></label><label class="wide">Responsável<input name="resource" value="Consultor" required></label><label class="wide"><span><input type="checkbox" name="is_demo"> Horário fictício para o simulador</span></label><small class="wide">Duração: 30 minutos. Horários sobrepostos são bloqueados.</small></div>`,f=>{const s=new Date(f.get('day')+'T'+f.get('time')+':00-03:00');if(s<=new Date())throw Error('Escolha um horário futuro.');return action('slot',{starts_at:s.toISOString(),ends_at:new Date(+s+1800000).toISOString(),resource:f.get('resource'),is_demo:f.has('is_demo')})})}
function bookLead(l){const free=slots.filter(s=>!!s.is_demo===!!l.is_demo&&s.enabled&&new Date(s.starts_at)>new Date()&&!bookings.some(b=>b.slot_id===s.id&&b.status==='confirmed'));modal('Agendar com '+esc(l.name||l.phone),`<label>Horário disponível<select name="slot_id" required><option value="">Selecione</option>${free.map(s=>`<option value="${s.id}">${date(s.starts_at)} · ${esc(s.resource)}</option>`).join('')}</select></label><p class="muted" style="margin-top:15px;font-size:12px">A reserva acontece ao confirmar. Depois, avise o lead pela conversa.</p>`,f=>action('book',{phone:l.phone,slot_id:f.get('slot_id')}),'Confirmar reunião')}
function configuration(){document.querySelector('#surface').innerHTML=`<div class="grid2"><form class="panel" id="settings"><h2>Operação</h2><div class="formgrid" style="margin-top:24px"><label class="wide">Nome do negócio<input name="business_name" value="${esc(settings.business_name)}" required></label><label class="wide">Contexto que orienta a IA<textarea name="business_context" rows="5" required>${esc(settings.business_context)}</textarea></label><label>Quente a partir de<input type="number" name="hot_threshold" value="${settings.hot_threshold||70}" min="50" max="100" required></label><label>Morno a partir de<input type="number" name="warm_threshold" value="${settings.warm_threshold||40}" min="1" max="49" required></label><label>SLA humano (minutos)<input name="sla_minutes" type="number" min="1" max="1440" value="${settings.sla_minutes||15}" required></label></div><button class="primary" style="margin-top:24px">Salvar regras</button></form><div class="panel"><h2>Qualificação transparente</h2><div class="risk"><strong>35 pontos · Aderência</strong>A empresa tem um processo B2B que pode ser automatizado.</div><div class="risk"><strong>25 pontos · Necessidade</strong>O lead descreveu uma dor ou objetivo concreto.</div><div class="risk"><strong>25 pontos · Momento</strong>Declarou prazo de até 30 dias.</div><div class="risk"><strong>15 pontos · Decisão</strong>É decisor ou participa da decisão de contratação.</div><p class="muted" style="font-size:12px;line-height:1.7;margin-top:18px">A IA extrai fatos; as regras calculam a pontuação. Ausência de informação não significa desinteresse. Orçamento é contexto, não barreira automática. Novos limites valem para as próximas avaliações.</p></div></div><div class="panel" style="margin-top:20px"><h2>Conexões da operação</h2><p class="muted" style="margin:15px 0;line-height:1.7">Supabase: banco, autenticação e atualizações ao vivo. n8n: dois fluxos — atendimento e entrega Telegram. Telegram: ambiente de teste. WhatsApp: representado visualmente no simulador; integração oficial fora do teste atual.</p><a href="https://autoconfi.app.n8n.cloud/" target="_blank" rel="noopener">Abrir n8n ↗</a> &nbsp; · &nbsp; <a href="https://supabase.com/dashboard/project/urgwupjlpoerkdkfunti" target="_blank" rel="noopener">Abrir Supabase ↗</a></div>`;document.querySelector('#settings').onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target));for(const k of ['hot_threshold','warm_threshold','sla_minutes'])p[k]=Number(p[k]);await action('settings',p)}}
function flow(){document.querySelector('#surface').innerHTML=`<div class="notice"><b>Dois fluxos, uma jornada.</b> Telegram é o canal de teste. O simulador visual de WhatsApp entra na mesma qualificação, sem conexão com a Meta.</div><div class="panel" style="margin-bottom:20px"><span class="badge blue">FLUXO 01 · ATENDIMENTO</span><h2 style="margin:15px 0 24px">Receber → Qualificar → CRM e agenda</h2><div class="flow-steps">${[['Identificar','Telefone e mensagem única'],['Conversar','IA extrai fatos com evidência'],['Qualificar','Regras calculam o score'],['Agendar e transferir','Horários reais ou fictícios isolados']].map((x,i)=>`<div class="flow-box"><em>0${i+1}</em><strong>${x[0]}</strong><span>${x[1]}</span></div>`).join('')}</div><p class="muted" style="line-height:1.8;margin-top:22px">Lead quente cria prioridade humana. Assumir ou pausar interrompe a IA. O simulador conectado passa por este mesmo fluxo e recebe a resposta no CRM.</p><a href="https://autoconfi.app.n8n.cloud/workflow/i8MOp5VaXEcng8SZ" target="_blank" rel="noopener">Abrir atendimento no n8n ↗</a></div><div class="panel"><span class="badge green">FLUXO 02 · ENTREGA TELEGRAM</span><h2 style="margin:15px 0 24px">Enviar → Confirmar resultado</h2><div class="flow-steps">${[['Ler respostas pendentes','Bot e vendedor na mesma fila'],['Conferir controle humano','Pausa e versão antes de enviar'],['Entregar no Telegram','Registrar sucesso, falha ou incerteza']].map((x,i)=>`<div class="flow-box"><em>0${i+1}</em><strong>${x[0]}</strong><span>${x[1]}</span></div>`).join('')}</div><p class="muted" style="line-height:1.8;margin-top:22px">Executa a cada minuto. O simulador não usa este envio e nunca dispara mensagens em números reais.</p><a href="https://autoconfi.app.n8n.cloud/workflow/DS09OVYC0j9mR1mU" target="_blank" rel="noopener">Abrir entrega no n8n ↗</a></div><h2 class="section-title">O que explicar no teste</h2><div class="grid2">${[['IA com limites','A IA conversa e extrai; o banco calcula a pontuação e confirma a reserva. Evidências reduzem erros, sem eliminar todos.'],['Humano no controle','Assumir e pausar cancelam respostas pendentes. Mensagens já em trânsito podem chegar.'],['Sem duplicação','Telefone identifica o lead. Evento único evita repetir mensagens; reserva exclusiva evita conflito de agenda.'],['Simulação honesta','Ensaio guiado funciona sem IA. Modo conectado usa Anthropic no n8n e horários fictícios separados da operação real.']].map(x=>`<div class="panel"><h3>${x[0]}</h3><p class="muted" style="font-size:12px;line-height:1.8;margin-top:10px">${x[1]}</p></div>`).join('')}</div>`}

async function action(type,p){try{if(demo){const l=leads.find(l=>l.phone===p.phone);if(type==='create_lead'){if(leads.some(l=>l.phone===p.phone))throw Error('Este telefone já existe.');leads.unshift({...p,stage:'new',mode:'bot',score:0,temperature:'unknown',channel:'manual',reasons:[],created_at:today.toISOString()})}else if(type==='stage')l.stage=p.stage;else if(type==='mode'){l.mode=p.mode;if(p.mode==='human'){l.human_owner='João Paulo';tasks=tasks.filter(t=>t.phone!==l.phone)}}else if(type==='edit')Object.assign(l,p);else if(type==='send')messages.push({id:crypto.randomUUID(),phone:p.phone,direction:'out',author:'human',body:p.body,status:'sent',created_at:new Date().toISOString()});else if(type==='settings')settings=p;else if(type==='slot'){if(p.is_demo)p.resource='Simulador (fictício)';if(slots.some(s=>s.resource===p.resource&&s.starts_at<p.ends_at&&s.ends_at>p.starts_at))throw Error('Este horário se sobrepõe a outro.');slots.push({...p,id:crypto.randomUUID(),enabled:true})}else if(type==='book'){if(bookings.some(b=>b.status==='confirmed'&&(b.phone===p.phone||b.slot_id===p.slot_id)))throw Error('Lead ou horário já reservado.');bookings.push({...p,id:crypto.randomUUID(),status:'confirmed'});l.stage='meeting'}else if(type==='cancel_booking'){bookings.find(b=>b.id===p.id).status='cancelled'}else if(type==='close_slot')slots.find(s=>s.id===p.id).enabled=false;renderView();toast('Atualizado na demonstração.');return}const {error}=await db.rpc('orbita_operator',{p_action:type,p});if(error)throw error;await refresh();toast(type==='send'?'Mensagem na fila de envio.':'Salvo.')}catch(e){toast(e.message||'Não foi possível salvar.');throw e}}
async function refresh(){if(demo||!session)return;const tables=['leads','messages','slots','bookings','tasks','settings','events','simulator_requests'];const all=await Promise.all(tables.map(t=>db.from('orbita_'+t).select('*').order(t==='slots'?'starts_at':t==='settings'?'id':'created_at',{ascending:t==='slots'}).limit(t==='messages'?1000:500)));const error=all.find(r=>r.error)?.error;if(error)throw error;[leads,messages,slots,bookings,tasks]=all.slice(0,5).map(r=>r.data);messages.sort((a,b)=>a.created_at.localeCompare(b.created_at));settings=all[5].data[0]||{};events=all[6].data;simRequests=all[7].data;const sf=document.querySelector('#sim-message');if(sf)simDraft=sf.value;const focus=document.activeElement;const reply=document.querySelector('#reply');if(reply&&selected)drafts[selected]=reply.value;const caret=reply&&focus===reply?reply.selectionStart:null;const simCaret=sf&&focus===sf?sf.selectionStart:null;if(view==='settings'||document.querySelector('dialog[open]'))return;render();if(caret!==null){const next=document.querySelector('#reply');if(next&&!next.disabled){next.focus();next.setSelectionRange(caret,caret)}}if(simCaret!==null){const next=document.querySelector('#sim-message');if(next){next.focus();next.setSelectionRange(simCaret,simCaret)}}}
showLogin=()=>{document.querySelector('#content').innerHTML=`<div class="panel login"><span class="badge blue">ACESSO À OPERAÇÃO</span><h2 style="margin-top:20px">Seu CRM, protegido.</h2><p>Use o e-mail autorizado. Se o projeto ainda usa o e-mail de teste do Supabase, configure o provedor de e-mail no painel antes do primeiro acesso.</p><form id="login"><label>E-mail<input type="email" value="l2mortal01@gmail.com" id="email" required></label><button class="primary">Enviar link de acesso</button></form><details style="margin-top:20px"><summary>Tenho um código de acesso</summary><form id="verify"><label style="margin-top:15px">Código do e-mail<input id="otp" inputmode="numeric" required></label><button>Confirmar código</button></form></details><button id="backdemo">Voltar à demonstração</button><p id="loginstatus" role="status"></p></div>`;document.querySelector('#backdemo').onclick=()=>render();document.querySelector('#login').onsubmit=async e=>{e.preventDefault();try{await initDb();const {error}=await db.auth.signInWithOtp({email:document.querySelector('#email').value,options:{emailRedirectTo:location.origin}});if(error)throw error;document.querySelector('#loginstatus').textContent='Solicitação enviada. Abra o e-mail para entrar. Confira também a pasta de spam.'}catch(err){document.querySelector('#loginstatus').textContent=err.message}};document.querySelector('#verify').onsubmit=async e=>{e.preventDefault();try{await initDb();const {error}=await db.auth.verifyOtp({email:document.querySelector('#email').value,token:document.querySelector('#otp').value,type:'email'});if(error)throw error;await activate()}catch(err){document.querySelector('#loginstatus').textContent=err.message}}};
async function initDb(){if(db)return;const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2.57.4');db=createClient(SB_URL,SB_KEY,{auth:{detectSessionInUrl:true,persistSession:true}});}
async function activate(){const {data}=await db.auth.getSession();session=data.session;if(!session)return;const {data:allowed,error}=await db.rpc('orbita_is_operator');if(error||!allowed){await db.auth.signOut();session=null;throw Error('Este e-mail não está autorizado para a operação.')}demo=false;await refresh();if(realtime)await db.removeChannel(realtime);realtime=db.channel('orbita-live');for(const table of ['orbita_leads','orbita_messages','orbita_slots','orbita_bookings','orbita_tasks','orbita_simulator_requests'])realtime.on('postgres_changes',{event:'*',schema:'public',table},()=>scheduleRefresh());realtime.subscribe(status=>{connectionState=status==='SUBSCRIBED'?'● Ao vivo · Supabase':status==='CHANNEL_ERROR'?'Reconectando · atualização a cada 15s':'CRM conectado';const e=document.querySelector('#connection');if(e&&!demo)e.textContent=connectionState});}
let refreshTimer;function scheduleRefresh(){clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>refresh().catch(e=>toast(e.message)),350)}
let simRequests=[],simDraft='',simHumanDraft='',simBusy=false;
const simPhones={demo:sessionStorage.getItem('orbita-sim-demo'),live:sessionStorage.getItem('orbita-sim-live')};
function simulatorPhone(){const key=demo?'demo':'live';if(!simPhones[key]){simPhones[key]='+999'+String(crypto.getRandomValues(new Uint32Array(1))[0]).padStart(10,'0');sessionStorage.setItem('orbita-sim-'+key,simPhones[key])}return simPhones[key]}
function simNew(){const key=demo?'demo':'live';simPhones[key]=null;simDraft='';simHumanDraft='';simulatorPhone();simulator()}
function simAddMessage(l,body,author='bot'){messages.push({id:crypto.randomUUID(),phone:l.phone,channel:'demo',body,author,direction:author==='lead'?'in':'out',status:author==='lead'?'received':'sent',created_at:new Date().toISOString(),revision:l.revision})}
function simDemoLead(){const phone=simulatorPhone();let l=leads.find(x=>x.phone===phone);if(!l){l={phone,name:null,company:null,channel:'demo',is_demo:true,stage:'new',mode:'bot',temperature:'unknown',score:0,reasons:[],qualification:{},revision:0,created_at:new Date().toISOString(),updated_at:new Date().toISOString()};leads.unshift(l)}return l}
function simGuided(text){const l=simDemoLead();l.revision++;simAddMessage(l,text,'lead');const s=text.trim();
 if(/^(parar|sair|stop)[.! ]*$/i.test(s)){l.mode='optout';simAddMessage(l,'Tudo bem. O atendimento automático foi encerrado.','system');return}
 if(/(?:falar|conversar).*(?:humano|pessoa|vendedor|atendente)/i.test(s)){l.mode='human';simTask(l,'Você pediu uma pessoa da equipe.');simAddMessage(l,'Vou encaminhar sua conversa para uma pessoa da equipe.','system');return}
 if(l.mode!=='bot')return;
 if(/^[1-3]$/.test(s)&&l.offered_slots?.length){const sl=l.offered_slots[Number(s)-1];if(!sl||bookings.some(b=>b.status==='confirmed'&&(b.slot_id===sl.id||b.phone===l.phone))){simAddMessage(l,'Esse horário não está disponível. Vou pedir apoio à equipe.');l.mode='human';return}bookings.push({id:crypto.randomUUID(),phone:l.phone,slot_id:sl.id,status:'confirmed'});l.stage='meeting';l.offered_slots=[];if(l.temperature==='hot')l.mode='human';simAddMessage(l,'Reunião simulada confirmada para '+date(sl.starts_at)+' (Brasília). A equipe continuará por aqui.','system');return}
 const facts=extractGuided(s,l.demoQuestion);l.qualification={...l.qualification,...facts};if(facts.name)l.name=facts.name;if(facts.company)l.company=facts.company;Object.assign(l,qualify(l.qualification,settings));l.stage=l.temperature==='hot'?'qualified':'qualifying';l.summary=[l.name,l.company,l.qualification.need,l.qualification.urgency==='30_days'?'Prazo de até 30 dias':null,l.qualification.decision==='decision_maker'?'Decisor':null].filter(Boolean).join(' · ');
 if(l.temperature==='hot'||/reunião|agendar|agenda|horário/i.test(s)){if(l.temperature==='hot')simTask(l,'Lead quente: assumir conversa');if(!slots.some(x=>x.is_demo)){const start=new Date();start.setDate(start.getDate()+1);start.setHours(10,0,0,0);for(let i=0;i<3;i++){const t=new Date(+start+i*3600000);slots.push({id:crypto.randomUUID(),starts_at:t.toISOString(),ends_at:new Date(+t+1800000).toISOString(),resource:'Simulador (fictício)',enabled:true,is_demo:true})}}
 const free=slots.filter(x=>x.is_demo&&x.enabled&&new Date(x.starts_at)>new Date()&&!bookings.some(b=>b.slot_id===x.id&&b.status==='confirmed')).slice(0,3);l.offered_slots=free;simAddMessage(l,free.length?'Seu cenário tem aderência. Podemos reservar um diagnóstico de 30 minutos?\n'+free.map((x,i)=>(i+1)+' — '+date(x.starts_at)).join('\n')+'\nResponda 1, 2 ou 3. Horários fictícios, de Brasília.':'Não há horários fictícios livres. A equipe pode abrir novas disponibilidades.');return}
 const prompts=[['name','Olá! Sou a assistente virtual da Órbita. Como você se chama?'],['company','Obrigado! Qual é o nome da sua empresa?'],['need','Qual processo da empresa você gostaria de automatizar?'],['urgency','Você tem um prazo em mente para começar?'],['decision','Você participa da decisão de contratação?']];const next=prompts.find(([k])=>!l.qualification[k]);l.demoQuestion=next?.[0];simAddMessage(l,next?.[1]||'Já registrei o contexto. Você gostaria de agendar um diagnóstico?');
}
function simTask(l,title){if(!tasks.some(t=>t.phone===l.phone&&t.status==='open'))tasks.push({id:crypto.randomUUID(),phone:l.phone,title,status:'open',kind:'handoff',due_at:new Date(Date.now()+15*60000).toISOString()});l.handoff_requested_at=new Date().toISOString()}
async function simSend(text){if(simBusy||!text.trim())return;simBusy=true;const body=text.trim(),phone=simulatorPhone();simDraft='';try{if(demo){simGuided(body)}else{const {data,error}=await db.rpc('orbita_simulator_enqueue',{p_phone:phone,p_text:body,p_id:crypto.randomUUID()});if(error)throw error;simRequests.unshift({id:data.id,phone,body,status:data.status,created_at:new Date().toISOString()})}if(view==='simulator')simulator()}catch(e){simDraft=body;toast(e.message)}finally{simBusy=false;if(view==='simulator')simulator()}}
function simulator(){const phone=simulatorPhone(),l=leads.find(x=>x.phone===phone),q=simRequests.find(x=>x.phone===phone&&['pending','processing'].includes(x.status)),last=simRequests.find(x=>x.phone===phone),history=messages.filter(x=>x.phone===phone);const pending=!!q;
 const state=l?modeLabel(l):'Pronto para começar';
 const examples=['Meu nome é João Paulo','Trabalho na Alfa Serviços','Preciso automatizar o atendimento da minha empresa','Quero começar este mês','Sou o dono da empresa','Quero falar com um humano'];
 document.querySelector('#surface').innerHTML=`<div class="sim-top"><div><span class="badge ${demo?'warm':'green'}">${demo?'Ensaio guiado · sem IA real':'Conectado · IA no n8n'}</span><p>${demo?'Respostas locais por regras, para ensaiar agora. Nada é enviado ao Telegram ou WhatsApp.':'Conversa fictícia salva no Supabase e processada pela IA do fluxo 01. Nenhuma mensagem vai à Meta.'}</p></div><button id="sim-new">＋ Nova conversa</button></div><div class="sim-layout"><section class="phone-shell" aria-label="Simulador de conversa"><div class="phone-top"><span>9:41</span><span>SIMULAÇÃO</span><span>▰</span></div><header class="phone-head"><span class="wa-avatar">Ó</span><div><strong>Órbita Automação</strong><small>${demo?'Atendimento demonstrativo':'Assistente virtual · n8n'}</small></div><span class="phone-dots">⋮</span></header><div class="phone-messages"><span class="phone-date">Hoje · conversa de teste</span>${history.length?history.map(m=>`<div class="wa-bubble ${m.author==='lead'?'wa-mine':''}">${esc(m.body)}<small>${esc(m.author==='lead'?'Você, como lead':m.author==='human'?'Vendedor humano':m.author==='system'?'Sistema':demo?'Resposta guiada':'Assistente IA')} · ${new Date(m.created_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}${m.author==='lead'?' ✓✓':''}</small></div>`).join(''):'<div class="wa-welcome"><strong>Você faz o papel do lead.</strong><p>Envie uma mensagem e acompanhe o cadastro, a pontuação e a agenda ao lado.</p></div>'}${pending?`<div class="wa-wait">${q.status==='pending'?'Aguardando o fluxo 01 do n8n…':'IA processando a conversa…'}<small>A coleta acontece a cada minuto.</small></div>`:''}${last?.status==='failed'?`<div class="sim-error">${esc(last.error||'Confira a execução no n8n.')}</div>`:''}</div><form id="sim-send" class="wa-compose"><textarea id="sim-message" aria-label="Mensagem como lead" placeholder="Digite como se fosse o cliente…" rows="2" maxlength="4000" required>${esc(simDraft)}</textarea><button aria-label="Enviar mensagem no simulador" ${pending||simBusy?'disabled':''}>➤</button></form><div class="phone-caption">Interface inspirada no WhatsApp. Não é uma conexão com a Meta.</div></section><aside class="sim-inspector"><div class="panel"><span class="label-small">O CRM ENXERGA ISTO</span><div class="sim-lead-title"><h2>${esc(l?.name||'Novo contato')}</h2>${badge(l||{temperature:'unknown'})}</div><p class="muted">${esc(l?.company||'Empresa ainda não informada')}</p><p class="sim-id">Identidade fictícia: ${esc(phone)}</p><div class="sim-facts"><div><small>Etapa</small><strong>${esc([...stages,['lost','Encerrado']].find(x=>x[0]===l?.stage)?.[1]||'Novo')}</strong></div><div><small>Atendimento</small><strong>${state}</strong></div></div><div class="scorebox"><strong class="sim-score">${l?.score||0}<span>/100</span></strong>${(l?.reasons||[]).map(r=>`<div class="reason"><span>${esc(r.label)}</span><strong>+${r.points}</strong></div>`).join('')||'<p class="muted">A pontuação aparece conforme a conversa evolui.</p>'}</div><p class="sim-summary">${esc(l?.summary||'As informações surgem aqui sem preencher o cadastro manualmente.')}</p>${bookings.some(b=>b.phone===phone&&b.status==='confirmed')?'<div class="sim-booked">✓ Reunião simulada confirmada na agenda</div>':''}<div class="actions" style="margin-top:18px"><button id="sim-open" ${!l?'disabled':''}>Ver no CRM ↗</button><button id="sim-take" ${!l||l.mode==='optout'?'disabled':''}>${l?.mode==='human'?'Retomar IA':'Assumir conversa'}</button><button id="sim-pause" ${!l||l.mode==='optout'?'disabled':''}>${l?.mode==='paused'?'Retomar':'Pausar'}</button></div>${l?.mode==='human'?`<form id="sim-human" class="sim-human"><label>Responder como vendedor<textarea id="sim-human-text" rows="2" required maxlength="4000">${esc(simHumanDraft)}</textarea></label><button class="primary">Enviar como vendedor</button></form>`:''}</div><div class="panel"><h3>${demo?'Experimente esta sequência':'Como usar o teste conectado'}</h3><p class="muted" style="font-size:12px;line-height:1.8;margin:12px 0">${demo?'Clique em uma sugestão para preencher a mensagem; você decide quando enviar. O ensaio é determinístico e tem vocabulário limitado.':'Publique o fluxo 01 com a credencial HTTP e Anthropic. A mensagem entra na fila autenticada; o n8n usa a mesma IA e regras do Telegram. Horários fictícios são separados dos horários reais.'}</p><div class="sim-examples">${examples.map((x,i)=>`<button data-example="${i}">${esc(x)}</button>`).join('')}</div><p class="muted" style="font-size:11px;line-height:1.7;margin-top:16px">${demo?'Para testar o modelo real, use “Conectar meu CRM”.':'Se ficar aguardando, verifique se o fluxo 01 está publicado e se a credencial HTTP está selecionada.'}</p></div></aside></div>`;
 document.querySelector('#sim-new').onclick=simNew;
 const field=document.querySelector('#sim-message');field.oninput=()=>simDraft=field.value;
 document.querySelector('#sim-send').onsubmit=e=>{e.preventDefault();if(!pending)simSend(field.value)};
 document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{simDraft=examples[+b.dataset.example];field.value=simDraft;field.focus()});
 document.querySelector('#sim-open').onclick=()=>openLead(phone);
 document.querySelector('#sim-take').onclick=()=>action('mode',{phone,mode:l.mode==='human'?'bot':'human'}).catch(()=>{});
 document.querySelector('#sim-pause').onclick=()=>action('mode',{phone,mode:l.mode==='paused'?'bot':'paused'}).catch(()=>{});
 const human=document.querySelector('#sim-human');if(human){const f=document.querySelector('#sim-human-text');f.oninput=()=>simHumanDraft=f.value;human.onsubmit=async e=>{e.preventDefault();const body=f.value.trim();if(!body)return;simHumanDraft='';try{await action('send',{phone,body,request_id:crypto.randomUUID()})}catch{simHumanDraft=body;if(view==='simulator')simulator()}}}
 const body=document.querySelector('.phone-messages');body.scrollTop=body.scrollHeight;
}

resetDemo();if(location.hash==='#simulador')view='simulator';render();initDb().then(()=>activate()).catch(e=>toast(e.message));
setInterval(()=>{if(session&&!demo&&!document.querySelector('dialog[open]')&&document.activeElement?.tagName!=='TEXTAREA'&&document.activeElement?.tagName!=='INPUT')refresh().catch(()=>toast('Conexão indisponível. Seus dados salvos permanecem no banco.'))},15000);
const mc=document.modelContext;if(mc?.registerTool){mc.registerTool({name:'list_visible_leads',description:'Consulta os leads carregados nesta operação; retorna se são dados de demonstração.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async()=>({demo,leads:filtered().map(({phone,name,stage,score,temperature})=>({phone,name,stage,score,temperature}))})});mc.registerTool({name:'open_lead_conversation',description:'Abre a conversa de um lead existente. Não envia mensagens nem altera o cadastro.',inputSchema:{type:'object',properties:{phone:{type:'string'}},required:['phone'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async p=>{if(!p||typeof p.phone!=='string'||!leads.some(l=>l.phone===p.phone))throw Error('Lead inexistente');openLead(p.phone);return{opened:p.phone,demo}}})}
